`timescale 1ns / 1ps
// Throwaway harness around the lab's own sim/cmu_sim.v stimulus.
// Expected final counts per the comments in sim/inst.v:
//   total clocks = 18+18+1+1+18+18+1+35+18 = 128
//   instructions = 9 (indices 0..8 valid)
//   hits         = 3 (insts 2, 3, 6)
module tb_cmu_sim;
    reg clk = 0, rst = 1;
    wire [7:0] clk_count, inst_count, hit_count;

    cmu_sim uut(.clk(clk), .rst(rst),
                .clk_count(clk_count), .inst_count(inst_count), .hit_count(hit_count));

    initial begin
        #95 rst = 0;
    end
    always #10 clk = ~clk;

    initial begin
        #5000;
        $display("cmu_sim final: clk_count=%0d inst_count=%0d hit_count=%0d",
                 clk_count, inst_count, hit_count);
        if (clk_count == 128 && inst_count == 9 && hit_count == 3)
            $display("CMU_SIM RESULT: PASS");
        else
            $display("CMU_SIM RESULT: FAIL (expected clk=128 inst=9 hit=3)");
        $finish;
    end
endmodule
